use vstd::prelude::*;

verus! {

fn reverse(v: &mut Vec<u64>)
    ensures
        v@ == old(v)@.reverse(),
{
    let n: usize = v.len();
    let mut i: usize = 0;

    while i < n / 2
        invariant
            n == v.len(),
            i <= n / 2,
            // Elements already swapped to their reversed positions
            forall|k: int| 0 <= k < i ==> v@[k] == old(v)@[n as int - 1 - k],
            forall|k: int| 0 <= k < i ==> v@[n as int - 1 - k] == old(v)@[k],
            // Middle region not yet swapped remains unchanged so far
            forall|k: int| i <= k && k < n as int - i ==> v@[k] == old(v)@[k],
        decreases (n / 2) - i,
    {
        let j: usize = n - 1 - i;

        // Save old values at i and j, then swap.
        let tmp: u64 = v[i];
        v.set(i, v[j]);
        v.set(j, tmp);

        i = i + 1;
    }

    // From the loop invariants at i == n/2, the whole vector matches old(v) reversed.
}

} // verus!

